/// One built-in look of the carousel.
@immutable
final class BuiltinLookInfo {
  /// Creates the entry.
  const BuiltinLookInfo(this.id, this.swatch);

  /// The preset id (`teal_orange`): the `BuiltinLook.presetId` and the asset's file name.
  final String id;

  /// Three colours of the placeholder gradient (dark, mid, light).
  final List<Color> swatch;

  /// The display name.
  String get name => ColorStrings.lookName(id);
}

/// The 12 built-in looks, in carousel order (ux.md §10.7).
abstract final class BuiltinLooks {
  /// All of them.
  static const List<BuiltinLookInfo> all = <BuiltinLookInfo>[
    BuiltinLookInfo('teal_orange', [Color(0xFF0E5C6B), Color(0xFF2A8C8C), Color(0xFFE8913A)]),
    BuiltinLookInfo('warm', [Color(0xFF7A4A2A), Color(0xFFD9893B), Color(0xFFFFD79A)]),
    BuiltinLookInfo('cool', [Color(0xFF1E3A5F), Color(0xFF4F86B8), Color(0xFFBFE0FF)]),
    BuiltinLookInfo('vivid', [Color(0xFFE11D48), Color(0xFFF59E0B), Color(0xFF10B981)]),
    BuiltinLookInfo('matte', [Color(0xFF4A4A52), Color(0xFF7C7A80), Color(0xFFCFCBC8)]),
    BuiltinLookInfo('fade', [Color(0xFF6B6F7A), Color(0xFF9BA0AB), Color(0xFFD9DCE3)]),
    BuiltinLookInfo('mono', [Color(0xFF111111), Color(0xFF7A7A7A), Color(0xFFF2F2F2)]),
    BuiltinLookInfo('noir', [Color(0xFF000000), Color(0xFF3B3B3B), Color(0xFFE6E6E6)]),
    BuiltinLookInfo('sepia', [Color(0xFF3B2412), Color(0xFF8A5A2B), Color(0xFFE9CFA0)]),
    BuiltinLookInfo('vintage', [Color(0xFF3A3326), Color(0xFF9B8660), Color(0xFFE9D9B5)]),
    BuiltinLookInfo('cinematic', [Color(0xFF0B2A3A), Color(0xFF5C6F73), Color(0xFFF0B27A)]),
    BuiltinLookInfo('pastel', [Color(0xFFE8B4C8), Color(0xFFB8C8F0), Color(0xFFFFF1C9)]),
  ];

  /// The look [id], or null.
  static BuiltinLookInfo? byId(String id) {
    for (final l in all) {
      if (l.id == id) return l;
    }
    return null;
  }
}

// =================================================================================================
// .cube import
// =================================================================================================

/// The outcome of importing a LUT.
sealed class LutImportResult {
  const LutImportResult();
}

/// The picker was dismissed.
final class LutImportCancelled extends LutImportResult {
  /// Creates the result.
  const LutImportCancelled();
}

/// The LUT is in the pool as [asset]; [notice] is the parser's note (a 1D LUT was converted).
final class LutImported extends LutImportResult {
  /// Creates the result.
  const LutImported(this.asset, {this.notice});

  /// The project-owned LUT asset.
  final MediaAsset asset;

  /// A note worth showing, or null.
  final String? notice;
}

/// The LUT could not be added; [message] is ready to show.
final class LutImportFailed extends LutImportResult {
  /// Creates the result.
  const LutImportFailed(this.message);

  /// Copy for the user.
  final String message;
}

/// Reads the bytes of a picked LUT, or null when Dart cannot (a `content://` URI the pool service
/// copies itself); then the pool service alone judges the file.
typedef LutBytesReader = Future<Uint8List?> Function(PickedMedia picked);

/// Picks, validates and imports `.cube` files (ux.md §10.7).
class LutImporter {
  /// Creates the importer over the engine's [picker] and the media [pool].
  LutImporter({required this.picker, required this.pool, LutBytesReader? readBytes}) : readBytes = readBytes ?? _readFile;

  /// The system picker.
  final MediaPicker picker;

  /// The pool service (CORE-27).
  final MediaPoolService pool;

  /// Reads a pick.
  final LutBytesReader readBytes;

  /// Shows the Files picker for `.cube` files and imports the choice.
  Future<LutImportResult> pickAndImport(EditSession session) async {
    final picks = await picker.pick(const MediaPickRequest(source: MediaPickSource.files, kinds: {MediaPickKind.lut}, multiple: false));
    if (picks.isEmpty) return const LutImportCancelled();
    return importPick(session, picks.first);
  }

  /// Validates [picked] (parse in an isolate, so a bad file is explained with its line) and imports it.
  Future<LutImportResult> importPick(EditSession session, PickedMedia picked) async {
    String? notice;
    try {
      final bytes = await readBytes(picked);
      if (bytes != null) {
        final parsed = await Isolate.run(() {
          final lut = CubeLut.parse(bytes);
          return (lut.size, lut.notice);
        });
        notice = parsed.$2;
      }
    } on LutFormatException catch (e) {
      return LutImportFailed(messageOf(e));
    } on FileSystemException {
      return const LutImportFailed(ColorStrings.lutCannotOpen);
    }
    final List<Object> outcomes;
    try {
      outcomes = await pool.import(session, [picked]);
    } on Object {
      return const LutImportFailed(ColorStrings.lutFailed);
    }
    if (outcomes.isEmpty) return const LutImportFailed(ColorStrings.lutFailed);
    final outcome = outcomes.first;
    if (outcome is ImportedMedia) {
      if (outcome.asset.kind != MediaKind.lut) return const LutImportFailed(ColorStrings.lutFailed);
      return LutImported(outcome.asset, notice: notice);
    }
    return LutImportFailed(reasonCopy(outcome is ImportRejected ? outcome.reason : ''));
  }

  /// "This LUT couldn't be read (line 14: expected 3 numbers)." for a parser error.
  static String messageOf(LutFormatException e) {
    if (e.message.contains(lutTooLargeMessage)) return ColorStrings.lutTooLarge;
    var detail = e.message.trim();
    final prefix = RegExp(r'^Line \d+:\s*').firstMatch(detail);
    if (prefix != null) detail = detail.substring(prefix.end);
    while (detail.endsWith('.')) {
      detail = detail.substring(0, detail.length - 1);
    }
    return ColorStrings.lutUnreadable(line: e.line, detail: detail);
  }

  /// Copy for an `ImportRejected.reason` of the pool service.
  static String reasonCopy(String reason) => switch (reason) {
        'lutInvalid' => ColorStrings.lutUnreadable(),
        'notFound' || 'accessDenied' || 'notPersistable' || 'empty' => ColorStrings.lutCannotOpen,
        'diskFull' => ColorStrings.lutDiskFull,
        _ => ColorStrings.lutFailed,
      };

  static Future<Uint8List?> _readFile(PickedMedia picked) async {
    final uri = Uri.tryParse(picked.uri);
    if (uri == null || uri.scheme != 'file') return null;
    final file = File.fromUri(uri);
    if (await file.length() > maxCubeBytes) throw const LutFormatException(lutTooLargeMessage);
    return file.readAsBytes();
  }
}

/// The importer of the app (the engine's picker and the pool service).
final lutImporterProvider = Provider<LutImporter>(
  (ref) => LutImporter(picker: ref.watch(editorEngineProvider).picker, pool: ref.watch(mediaPoolServiceProvider)),
  name: 'lutImporterProvider',
);

// =================================================================================================
// Look stills
// =================================================================================================

/// A look to render a thumbnail for: [key] is the preset id or the LUT asset id.
@immutable
final class LookStillRequest {
  /// A bundled look.
  const LookStillRequest.builtin(String presetId)
      : key = presetId,
        lut = null;

  /// An imported LUT.
  const LookStillRequest.imported(MediaAsset asset)
      : key = '',
        lut = asset;

  /// The preset id, or ''.
  final String key;

  /// The LUT asset, or null for a bundled look.
  final MediaAsset? lut;

  /// The id the result is filed under.
  String get id => lut?.id ?? key;
}

/// Renders the look thumbnails of the carousel (JPEG bytes by [LookStillRequest.id]).
abstract interface class LookStillService {
  /// Stills of [item] at the playhead with each of [looks]; entries that cannot be made are absent.
  Future<Map<String, Uint8List>> render({
    required PreviewSession preview,
    required ItemId item,
    required List<LookStillRequest> looks,
    required int heightPx,
  });
}

/// [LookStillService] over `PreviewSession.renderLookStills`: bundled looks come from
/// [BundledLookFiles] (extracted on first use), imported LUTs from the `.vlut` beside the `.cube`.
final class EngineLookStillService implements LookStillService {
  /// Creates the service.
  EngineLookStillService({required this.roots, BundledLookFiles? bundled}) : bundled = bundled ?? BundledLookFiles(roots: roots);

  /// App roots.
  final StoreRoots roots;

  /// The bundled-look extractor.
  final BundledLookFiles bundled;

  @override
  Future<Map<String, Uint8List>> render({
    required PreviewSession preview,
    required ItemId item,
    required List<LookStillRequest> looks,
    required int heightPx,
  }) async {
    final specs = <LookSpec>[];
    for (final request in looks) {
      final spec = await _specOf(request);
      if (spec != null) specs.add(spec);
    }
    if (specs.isEmpty) return const {};
    final stills = await preview.renderLookStills(item, specs, heightPx: heightPx);
    return {
      for (var i = 0; i < specs.length && i < stills.length; i++)
        if (stills[i].isNotEmpty) specs[i].id: stills[i],
    };
  }

  Future<LookSpec?> _specOf(LookStillRequest request) async {
    try {
      final lut = request.lut;
      if (lut == null) {
        final resolved = await bundled.resolve(request.key);
        return resolved == null ? null : LookSpec(id: request.key, lutUri: resolved.uri, lutSize: resolved.size);
      }
      final locator = lut.locator;
      if (locator is! AppRelativeLocator) return null;
      final path = roots.resolve(ManagedStore.vlutOf(locator));
      final n = await readVlutTableSize(path);
      return n == null ? null : LookSpec(id: lut.id, lutUri: Uri.file(path).toString(), lutSize: n);
    } on Object {
      return null;
    }
  }
}

/// The thumbnail renderer of the app; null (swatches only) until the editor runtime is wired.
final lookStillServiceProvider = Provider<LookStillService?>((ref) {
  final runtime = ref.watch(editorRuntimeProvider);
  return runtime == null ? null : EngineLookStillService(roots: runtime.roots);
}, name: 'lookStillServiceProvider');

