/// The Filters & LUT panel (ux.md §10.7).
class FiltersPanel extends ConsumerStatefulWidget {
  /// Creates the panel.
  const FiltersPanel({super.key, required this.route});

  /// What the panel edits.
  final FiltersInspector route;

  /// Height of the thumbnails requested from the engine.
  static const int stillHeightPx = 144;

  @override
  ConsumerState<FiltersPanel> createState() => _FiltersPanelState();
}

class _FiltersPanelState extends ConsumerState<FiltersPanel> {
  static const Duration _stillsDelay = Duration(milliseconds: 400);

  Map<String, Uint8List> _stills = const {};
  Timer? _stillsTimer;
  int _stillsSerial = 0;
  String? _stillsKey;
  ValueListenable<TimeUs>? _playhead;
  bool _busy = false;
  _ImportMessage? _message;

  EditorController get _editor => ref.read(editorControllerProvider(EditorScope.idOf(context)).notifier);

  MediaClip? _item() {
    final item = ref.read(editorControllerProvider(EditorScope.idOf(context))).project?.index.item(widget.route.item);
    return item is MediaClip && item.visual != null ? item : null;
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final playhead = ref.read(playheadProvider(EditorScope.idOf(context)));
    if (!identical(playhead, _playhead)) {
      _playhead?.removeListener(_onPlayhead);
      _playhead = playhead..addListener(_onPlayhead);
      _scheduleStills(Duration.zero);
    }
  }

  @override
  void didUpdateWidget(FiltersPanel oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.route.item != widget.route.item) _scheduleStills(Duration.zero);
  }

  @override
  void dispose() {
    _playhead?.removeListener(_onPlayhead);
    _stillsTimer?.cancel();
    super.dispose();
  }

  // ---- Thumbnails --------------------------------------------------------------------------------

  void _onPlayhead() => _scheduleStills(_stillsDelay);

  void _scheduleStills(Duration delay) {
    _stillsTimer?.cancel();
    _stillsTimer = Timer(delay, _loadStills);
  }

  List<MediaAsset> _luts() {
    final pool = ref.read(editorControllerProvider(EditorScope.idOf(context))).project?.pool;
    if (pool == null) return const [];
    return _sortedLuts(pool);
  }

  Future<void> _loadStills() async {
    if (!mounted) return;
    final id = EditorScope.idOf(context);
    final service = ref.read(lookStillServiceProvider);
    final session = ref.read(editorSessionProvider(id));
    final preview = session.preview;
    final item = _item();
    final t = ref.read(playheadProvider(id)).value;
    if (service == null || preview == null || item == null || t < item.start || t >= item.end) return;
    final luts = _luts();
    final key = '${item.id}|$t|${luts.map((l) => l.id).join(',')}';
    if (key == _stillsKey) return;
    _stillsKey = key;
    final serial = ++_stillsSerial;
    try {
      final stills = await service.render(
        preview: preview,
        item: item.id,
        looks: [for (final l in BuiltinLooks.all) LookStillRequest.builtin(l.id), for (final l in luts) LookStillRequest.imported(l)],
        heightPx: FiltersPanel.stillHeightPx,
      );
      if (mounted && serial == _stillsSerial) setState(() => _stills = stills);
    } on Object {
      if (serial == _stillsSerial) _stillsKey = null; // Retry on the next trigger; the swatches stay.
    }
  }

  // ---- Applying ------------------------------------------------------------------------------------

  void _apply(LookRef? look) {
    final item = _item();
    if (item != null) _editor.apply(SetLook([item.id], look));
  }

  double _intensity(MediaClip item) => item.visual?.look?.intensity ?? 1;

  void _pickBuiltin(MediaClip item, String presetId) => _apply(BuiltinLook(presetId, intensity: _intensity(item)));

  void _pickLut(MediaClip item, MediaAsset lut) => _apply(ImportedLut(lut.id, intensity: _intensity(item)));

  // ---- Import ----------------------------------------------------------------------------------------

  Future<void> _import() async {
    if (_busy) return;
    final id = EditorScope.idOf(context);
    final session = ref.read(editorSessionProvider(id)).editOrNull;
    if (session == null) return;
    final importer = ref.read(lutImporterProvider);
    setState(() {
      _busy = true;
      _message = null;
    });
    LutImportResult result;
    try {
      result = await importer.pickAndImport(session);
    } on Object {
      result = const LutImportFailed(ColorStrings.lutFailed);
    }
    if (!mounted) return;
    switch (result) {
      case LutImportCancelled():
        setState(() => _busy = false);
      case LutImportFailed(:final message):
        setState(() {
          _busy = false;
          _message = _ImportMessage(message, error: true);
        });
      case LutImported(:final asset, :final notice):
        setState(() {
          _busy = false;
          _message = notice == null ? null : _ImportMessage(notice, error: false);
        });
        final item = _item();
        if (item != null) _apply(ImportedLut(asset.id, intensity: _intensity(item)));
        if (mounted) DanaviewToast.show(context, ColorStrings.lutAdded(lutName(asset)), icon: Icons.check_circle_outline_rounded);
        _scheduleStills(Duration.zero);
    }
  }

  // ---- Rename and remove ---------------------------------------------------------------------------

  Future<void> _rename(MediaAsset lut) async {
    final name = await showDanaviewPrompt(
      context,
      title: ColorStrings.renameTitle,
      hint: ColorStrings.renameHint,
      initialValue: lutName(lut),
      confirmLabel: ColorStrings.renameConfirm,
      validator: (v) => v.trim().isEmpty ? ColorStrings.nameRequired : null,
    );
    if (name == null || !mounted) return;
    final trimmed = name.trim();
    if (trimmed.isEmpty || trimmed == lutName(lut)) return;
    _editor.applyPoolChange(UpdateAsset(lut.copyWith(displayName: trimmed)));
  }

  Future<void> _remove(MediaAsset lut) async {
    final id = EditorScope.idOf(context);
    final project = ref.read(editorControllerProvider(id)).project;
    if (project == null) return;
    final users = lutUsers(project, lut.id);
    final ok = await showDanaviewConfirm(
      context,
      title: ColorStrings.removeTitle(lutName(lut)),
      message: ColorStrings.removeMessage(users.length),
      confirmLabel: ColorStrings.removeConfirm,
      destructive: true,
    );
    if (!ok || !mounted) return;
    final editor = _editor;
    if (users.isNotEmpty) {
      final cleared = editor.apply(SetLook(users, null));
      if (!cleared.applied) return;
    }
    final removed = editor.applyPoolEdit(RemoveAssets({lut.id}), label: ColorStrings.removeFromProject);
    if (!mounted) return;
    if (removed.applied) {
      DanaviewToast.show(context, ColorStrings.lutRemoved(lutName(lut)), icon: Icons.check_circle_outline_rounded);
      _scheduleStills(Duration.zero);
    }
  }

  // ---- Build ---------------------------------------------------------------------------------------

  @override
  Widget build(BuildContext context) {
    final id = EditorScope.idOf(context);
    final item = ref.watch(editorControllerProvider(id).select((s) => s.project?.index.item(widget.route.item)));
    if (item is! MediaClip || item.visual == null) return const SizedBox.shrink();
    final pool = ref.watch(editorControllerProvider(id).select((s) => s.project?.pool));
    final ready = ref.watch(editorControllerProvider(id).select((s) => s.isReady));
    final locked = ref.watch(editorControllerProvider(id).select((s) => s.project?.index.locate(widget.route.item)?.track.locked ?? false));
    final enabled = ready && !locked;
    final look = item.visual!.look;
    final luts = pool == null ? const <MediaAsset>[] : _sortedLuts(pool);

    final looks = <Widget>[
      _LookTile(
        key: const ValueKey<String>('look.none'),
        label: ColorStrings.none,
        selected: look == null,
        enabled: enabled,
        onTap: () => _apply(null),
        thumb: const _NoneThumb(),
      ),
      for (final info in BuiltinLooks.all)
        _LookTile(
          key: ValueKey<String>('look.${info.id}'),
          label: info.name,
          selected: look is BuiltinLook && look.presetId == info.id,
          enabled: enabled,
          onTap: () => _pickBuiltin(item, info.id),
          thumb: _Thumb(bytes: _stills[info.id], colors: info.swatch),
        ),
    ];
    final lutTiles = <Widget>[
      for (final lut in luts)
        _LutTile(
          key: ValueKey<String>('lut.${lut.id}'),
          label: lutName(lut),
          selected: look is ImportedLut && look.lut == lut.id,
          enabled: enabled,
          onTap: () => _pickLut(item, lut),
          onRename: () => _rename(lut),
          onRemove: () => _remove(lut),
          thumb: _Thumb(bytes: _stills[lut.id], colors: const [Color(0xFF2A2D3E), Color(0xFF5E60EE), Color(0xFFC7CAFB)]),
        ),
    ];

    return InspectorHeaderActions.publish(
      actions: InspectorHeaderActions(onReset: look == null || !enabled ? null : _removeLook),
      child: CustomScrollView(
        slivers: [
          // No horizontal sliver padding: the carousels run edge to edge of the panel (and clip
          // there); every other row carries the panel inset itself.
          SliverToBoxAdapter(
            child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
              if (locked)
                _inset(Padding(
                  padding: const EdgeInsets.only(top: DanaviewSpacing.sm),
                  child: Text(ColorStrings.trackLocked, style: _hintStyle.copyWith(color: DanaviewColors.warning)),
                )),
              _inset(DanaviewSectionHeader(ColorStrings.looks, padding: const EdgeInsets.only(top: DanaviewSpacing.md, bottom: DanaviewSpacing.sm))),
              _Carousel(key: const ValueKey<String>('looks.carousel'), label: ColorStrings.looksLabel, children: looks),
              if (look != null) ...[
                const SizedBox(height: DanaviewSpacing.sm),
                _inset(InspectorPropertyRow(
                  key: const ValueKey<String>('row.look.intensity'),
                  item: item.id,
                  property: PropertyKeys.lookIntensity,
                  label: ColorStrings.intensity,
                )),
              ],
              _inset(DanaviewSectionHeader(
                ColorStrings.myLuts,
                padding: const EdgeInsets.only(top: DanaviewSpacing.lg, bottom: DanaviewSpacing.sm),
                action: DanaviewButton.secondary(
                  key: const ValueKey<String>('lut.import'),
                  label: _busy ? ColorStrings.importing : ColorStrings.importCube,
                  icon: Icons.upload_file_rounded,
                  size: DanaviewButtonSize.sm,
                  onPressed: enabled && !_busy ? _import : null,
                ),
              )),
              if (_message != null) _inset(_MessageView(message: _message!, onDismiss: () => setState(() => _message = null))),
              if (lutTiles.isEmpty)
                _inset(Padding(
                  padding: const EdgeInsets.only(bottom: DanaviewSpacing.sm),
                  child: Text(ColorStrings.noLuts, style: _hintStyle),
                ))
              else
                _Carousel(key: const ValueKey<String>('luts.carousel'), label: ColorStrings.lutsLabel, children: lutTiles),
              const SizedBox(height: DanaviewSpacing.lg),
            ]),
          ),
        ],
      ),
    );
  }

  void _removeLook() => _apply(null);
}

/// The imported LUT assets of [pool], oldest first.
List<MediaAsset> _sortedLuts(MediaPool pool) {
  final list = [
    for (final a in pool.assets.values)
      if (a.kind == MediaKind.lut) a
  ];
  list.sort((a, b) {
    final c = a.addedAt.compareTo(b.addedAt);
    return c != 0 ? c : a.id.compareTo(b.id);
  });
  return list;
}

/// The name of [lut] without its `.cube` extension.
String lutName(MediaAsset lut) {
  final name = lut.displayName;
  return name.toLowerCase().endsWith('.cube') ? name.substring(0, name.length - 5) : name;
}

/// The visual clips of [project] whose look is the LUT [lut].
List<ItemId> lutUsers(EditProject project, MediaId lut) {
  final out = <ItemId>[];
  for (final track in project.tracks) {
    for (final item in track.items) {
      if (item is! MediaClip) continue;
      final look = item.visual?.look;
      if (look is ImportedLut && look.lut == lut) out.add(item.id);
    }
  }
  return out;
}

/// The panel's horizontal content inset.
const double _panelPadding = DanaviewSpacing.lg;

/// A carousel's inset: the panel inset less the ring's room, so the pictures line up with the rows.
const EdgeInsets _carouselInset = EdgeInsets.symmetric(horizontal: _panelPadding - _ringInset);

/// [child] with the panel's horizontal inset.
Widget _inset(Widget child) => Padding(padding: const EdgeInsets.symmetric(horizontal: _panelPadding), child: child);

TextStyle get _hintStyle => DanaviewTextStyles.caption.copyWith(fontFamily: DanaviewFonts.family, color: DanaviewColors.textMuted);

@immutable
class _ImportMessage {
  const _ImportMessage(this.text, {required this.error});

  final String text;
  final bool error;
}

class _MessageView extends StatelessWidget {
  const _MessageView({required this.message, required this.onDismiss});

  final _ImportMessage message;
  final VoidCallback onDismiss;

  @override
  Widget build(BuildContext context) {
    final color = message.error ? DanaviewColors.errorLight : DanaviewColors.textSecondary;
    return Semantics(
      liveRegion: true,
      container: true,
      child: Container(
        key: const ValueKey<String>('lut.message'),
        margin: const EdgeInsets.only(bottom: DanaviewSpacing.sm),
        padding: const EdgeInsets.fromLTRB(DanaviewSpacing.md, DanaviewSpacing.xs, DanaviewSpacing.xs, DanaviewSpacing.xs),
        decoration: BoxDecoration(
          color: DanaviewColors.surfaceElevated,
          borderRadius: DanaviewRadius.mdAll,
          // Errors read from the icon and text colour; the edge stays a neutral hairline.
          border: const Border.fromBorderSide(DanaviewBorders.hairline),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Padding(
              padding: const EdgeInsets.only(top: DanaviewSpacing.xs + 2),
              child: Icon(message.error ? Icons.error_outline_rounded : Icons.info_outline_rounded, size: 18, color: color),
            ),
            const SizedBox(width: DanaviewSpacing.sm),
            Expanded(
              child: Padding(
                padding: const EdgeInsets.symmetric(vertical: DanaviewSpacing.sm),
                child: Text(message.text, style: DanaviewTextStyles.caption.copyWith(fontFamily: DanaviewFonts.family, color: color)),
              ),
            ),
            DanaviewIconButton(icon: Icons.close_rounded, iconSize: 18, size: 36, tooltip: 'Dismiss', onPressed: onDismiss),
          ],
        ),
      ),
    );
  }
}

/// A horizontally scrolling row of tiles (height from its content, so large text never overflows).
///
/// It spans the panel edge to edge and clips to its own bounds, so tiles scroll only inside the
/// panel (never over the tool rail or the preview); the inset lines the first and last tile up
/// with the panel's content.
class _Carousel extends StatelessWidget {
  const _Carousel({super.key, required this.label, required this.children});

  final String label;
  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    return Semantics(
      container: true,
      label: label,
      child: SingleChildScrollView(
        scrollDirection: Axis.horizontal,
        clipBehavior: Clip.hardEdge,
        padding: _carouselInset,
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            for (var i = 0; i < children.length; i++) ...[
              if (i > 0) const SizedBox(width: DanaviewSpacing.xs),
              children[i],
            ],
          ],
        ),
      ),
    );
  }
}

/// Size of a look tile's picture.
const double _thumbWidth = 88;
const Size _thumbSize = Size(_thumbWidth, 56);

/// Width of the selection ring drawn around the selected tile's picture.
const double _ringWidth = DanaviewSpacing.xxs;

/// Gap between the picture and its selection ring.
const double _ringGap = DanaviewSpacing.xxs;

/// Space the ring takes on each side of the picture (reserved on every tile so selecting one
/// never shifts the strip, and the ring never overlaps a neighbour).
const double _ringInset = _ringWidth + _ringGap;

/// Width of a whole tile: the picture plus the ring's room on both sides.
const double _tileWidth = _thumbWidth + 2 * _ringInset;

/// The ring's corner radius: the picture's radius grown by the ring's inset, so both curves share
/// a centre and the ring hugs the picture with an even gap.
const BorderRadius _ringRadius = BorderRadius.all(Radius.circular(DanaviewRadius.md + _ringInset));

class _LookTile extends StatelessWidget {
  const _LookTile({
    super.key,
    required this.label,
    required this.selected,
    required this.enabled,
    required this.onTap,
    required this.thumb,
    this.onLongPress,
    this.actions,
  });

  final String label;
  final bool selected;
  final bool enabled;
  final VoidCallback onTap;
  final VoidCallback? onLongPress;
  final Widget thumb;
  final Map<CustomSemanticsAction, VoidCallback>? actions;

  @override
  Widget build(BuildContext context) {
    return Semantics(
      customSemanticsActions: actions,
      child: DanaviewPressable(
        onTap: enabled ? onTap : null,
        onLongPress: enabled ? onLongPress : null,
        enabled: enabled,
        selected: selected,
        semanticLabel: ColorStrings.lookTile(label, selected: selected),
        borderRadius: _ringRadius,
        // Owner rule: no press or hover feedback; the ring is the selected state only.
        pressedScale: 1,
        pressedOpacity: 1,
        hoverColor: const Color(0x00000000),
        child: SizedBox(
          width: _tileWidth,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              // The ring sits outside the picture's clip, so its corners are never cut.
              DecoratedBox(
                key: const ValueKey<String>('look.ring'),
                decoration: BoxDecoration(
                  borderRadius: _ringRadius,
                  border: Border.all(color: selected ? DanaviewColors.primaryLight : const Color(0x00000000), width: _ringWidth),
                ),
                child: Padding(
                  padding: const EdgeInsets.all(_ringInset),
                  child: SizedBox.fromSize(
                    size: _thumbSize,
                    child: DecoratedBox(
                      position: DecorationPosition.foreground,
                      decoration: BoxDecoration(
                        borderRadius: DanaviewRadius.mdAll,
                        border: Border.all(color: DanaviewColors.border, width: DanaviewBorders.width),
                      ),
                      child: ClipRRect(borderRadius: DanaviewRadius.mdAll, child: thumb),
                    ),
                  ),
                ),
              ),
              const SizedBox(height: DanaviewSpacing.xxs),
              Text(
                label,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                textAlign: TextAlign.center,
                style: DanaviewTextStyles.caption.copyWith(
                  fontFamily: DanaviewFonts.family,
                  color: selected ? DanaviewColors.textPrimary : DanaviewColors.textSecondary,
                  fontWeight: selected ? FontWeight.w600 : FontWeight.w500,
                ),
              ),
              const SizedBox(height: DanaviewSpacing.xs),
            ],
          ),
        ),
      ),
    );
  }
}

/// An imported LUT: a tile with the Rename / Remove menu on long press and as semantics actions.
class _LutTile extends StatelessWidget {
  const _LutTile({
    super.key,
    required this.label,
    required this.selected,
    required this.enabled,
    required this.onTap,
    required this.onRename,
    required this.onRemove,
    required this.thumb,
  });

  final String label;
  final bool selected;
  final bool enabled;
  final VoidCallback onTap;
  final VoidCallback onRename;
  final VoidCallback onRemove;
  final Widget thumb;

  @override
  Widget build(BuildContext context) {
    return DanaviewMenuAnchor(
      width: 220,
      entries: [
        DanaviewMenuItem(label: ColorStrings.rename, icon: Icons.drive_file_rename_outline_rounded, onTap: onRename),
        DanaviewMenuItem(label: ColorStrings.removeFromProject, icon: Icons.delete_outline_rounded, destructive: true, onTap: onRemove),
      ],
      builder: (context, open, isOpen) => _LookTile(
        label: label,
        selected: selected,
        enabled: enabled,
        onTap: onTap,
        onLongPress: open,
        thumb: thumb,
        actions: {
          const CustomSemanticsAction(label: ColorStrings.rename): onRename,
          const CustomSemanticsAction(label: ColorStrings.removeFromProject): onRemove,
        },
      ),
    );
  }
}

/// A look's picture: the engine's still when there is one, else a diagonal swatch gradient.
class _Thumb extends StatelessWidget {
  const _Thumb({required this.bytes, required this.colors});

  final Uint8List? bytes;
  final List<Color> colors;

  @override
  Widget build(BuildContext context) {
    final swatch = DecoratedBox(
      decoration: BoxDecoration(gradient: LinearGradient(begin: Alignment.topLeft, end: Alignment.bottomRight, colors: colors)),
    );
    final data = bytes;
    if (data == null || data.isEmpty) return swatch;
    return Image.memory(
      data,
      fit: BoxFit.cover,
      gaplessPlayback: true,
      excludeFromSemantics: true,
      errorBuilder: (context, error, stack) => swatch,
    );
  }
}

class _NoneThumb extends StatelessWidget {
  const _NoneThumb();

  @override
  Widget build(BuildContext context) => const ColoredBox(
        color: DanaviewColors.surfaceElevated,
        child: Center(child: Icon(Icons.block_rounded, size: 22, color: DanaviewColors.textSecondary)),
      );
}
